target.css:
:root {
  --ink: #18251f;
  --muted: #66746b;
  --paper: #fffdf7;
  --line: #dbe3d9;
  --moss: #245f48;
  --mint: #dff1e6;
  --gold: #d99a36;
  --gold-pale: #fff0cf;
  --sky: #dcecf1;
}

* {
  box-sizing: border-box;
}

.flight-card {
  width: 500px;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 16px 13px;
  border-bottom: 1px solid var(--line);
}

.title-block p,
.title-block h1,
.bird-copy p,
.card-footer p {
  margin: 0;
}

.eyebrow {
  margin-bottom: 3px !important;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.title-block h1 {
  font-size: 20px;
  line-height: 1.1;
  letter-spacing: -0.03em;
}

.ready-pill {
  padding: 6px 9px;
  color: var(--moss);
  background: var(--mint);
  border-radius: 999px;
  font-size: 12px;
  font-weight: 800;
}

.panel-grid {
  display: grid;
  grid-template-columns: 1.2fr 0.8fr;
}

.bird-profile {
  display: flex;
  gap: 11px;
  padding: 14px 16px 11px;
  border-right: 1px solid var(--line);
}

.bird-mark {
  display: grid;
  width: 50px;
  height: 50px;
  flex: 0 0 50px;
  place-items: center;
  margin: 0;
  background: var(--gold-pale);
  border: 1px solid var(--gold);
  border-radius: 15px 15px 15px 4px;
  font-size: 27px;
}

.bird-copy {
  min-width: 0;
  flex: 1;
}

.name-row {
  display: flex;
  align-items: center;
  gap: 7px;
}

.name-row h2 {
  margin: 0;
  font-size: 17px;
  line-height: 1.15;
}

.tag {
  padding: 3px 6px;
  color: var(--moss);
  background: var(--mint);
  border-radius: 5px;
  font-size: 10px;
  font-weight: 800;
}

.bird-copy p {
  margin-top: 3px;
  color: var(--muted);
  font-size: 12px;
}

.check-list {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 7px;
  padding: 8px 0 0;
  margin: 0;
  list-style: none;
}

.check-list li {
  display: flex;
  flex-direction: column;
  gap: 1px;
  color: var(--muted);
  font-size: 10px;
}

.check-list strong {
  color: var(--ink);
  font-size: 12px;
}

.metrics {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  padding: 14px 10px 11px;
  background: var(--sky);
}

.metric {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 3px;
  padding-left: 9px;
  border-left: 1px solid var(--line);
}

.metric:first-child {
  padding-left: 0;
  border-left: 0;
}

.metric > span {
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
}

.metric strong {
  font-size: 16px;
  line-height: 1;
  letter-spacing: -0.04em;
}

.metric strong span {
  margin-left: 1px;
  color: var(--muted);
  font-size: 10px;
  letter-spacing: 0;
}

.route-panel {
  grid-column: 1 / -1;
  padding: 10px 16px 12px;
  border-top: 1px solid var(--line);
}

.route-heading,
.route-labels,
.card-footer,
.card-footer button {
  display: flex;
  align-items: center;
}

.route-heading {
  justify-content: space-between;
  font-size: 11px;
}

.route-heading span {
  color: var(--muted);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.route-heading strong {
  font-size: 12px;
}

.route-track {
  display: flex;
  align-items: center;
  height: 15px;
  padding: 0 3px;
}

.route-track i {
  height: 2px;
  flex: 1;
  background: var(--moss);
}

.route-track b {
  width: 8px;
  height: 8px;
  background: var(--paper);
  border: 2px solid var(--moss);
  border-radius: 50%;
}

.route-track b:nth-of-type(2) {
  width: 11px;
  height: 11px;
  background: var(--gold);
  border-color: var(--gold);
}

.route-labels {
  justify-content: space-between;
  color: var(--muted);
  font-size: 10px;
}

.card-footer {
  justify-content: space-between;
  padding: 10px 16px;
  background: var(--ink);
}

.card-footer p {
  color: var(--paper);
  font-size: 12px;
  font-weight: 700;
}

.dot {
  display: inline-block;
  width: 7px;
  height: 7px;
  margin-right: 5px;
  background: var(--gold);
  border-radius: 50%;
}

.card-footer button {
  gap: 8px;
  padding: 0;
  color: var(--paper);
  background: transparent;
  border: 0;
  font-size: 12px;
  font-weight: 800;
}

.card-footer button span {
  color: var(--gold);
  font-size: 17px;
  line-height: 0;
}

